// #732: the Deploy to Cloudflare button. The page it opens reads `package.json` (`cloudflare.bindings`,
// the text next to each field) and `.dev.vars.example` (one field per secret name). It must ask for
// only what the installer types; every other secret is generated by `npm run deploy` (#730).
import { describe, it, expect } from 'vitest';
import pkgRaw from '../package.json?raw';
import devVarsExample from '../.dev.vars.example?raw';
import devVarsReference from '../.dev.vars.reference?raw';
import exampleApp from '../wrangler.example.jsonc?raw';
import readme from '../README.md?raw';
import guide from '../docs/self-hosting.md?raw';
import gitignore from '../.gitignore?raw';

const BUTTON = 'https://deploy.workers.cloudflare.com/?url=https://github.com/DigiSavvy-Inc/howdee-crm';
const names = (src: string) => [...src.matchAll(/^([A-Z][A-Z0-9_]*)=/gm)].map((m) => m[1]);

describe('the Deploy to Cloudflare button', () => {
	it('is in the README and the self-hosting guide, pointing at the public repository', () => {
		for (const text of [readme, guide]) {
			expect(text).toContain(`(${BUTTON})`);
			expect(text).toContain('https://deploy.workers.cloudflare.com/button');
		}
	});

	it('.dev.vars.example asks for SETUP_TOKEN only, with no value', () => {
		expect(names(devVarsExample)).toEqual(['SETUP_TOKEN']);
		expect(devVarsExample).toMatch(/^SETUP_TOKEN=$/m);
	});

	it('the generated secrets are not on the page, but stay in the full reference list', () => {
		const generated = ['SESSION_SECRET', 'WEBHOOK_KEY', 'CRON_KEY', 'INGEST_KEY', 'MAIL_TOKEN_KEY'];
		for (const name of generated) {
			expect(names(devVarsExample)).not.toContain(name);
			expect(names(devVarsReference)).toContain(name);
		}
		expect(names(devVarsReference)).toContain('SETUP_TOKEN');
	});

	it('package.json describes the database, the bucket and the one secret field', () => {
		const pkg = JSON.parse(pkgRaw);
		const bindings = pkg.cloudflare?.bindings ?? {};
		const binding = (kind: string) => new RegExp(`"${kind}"[\\s\\S]*?"binding":\\s*"([A-Z_]+)"`).exec(exampleApp)?.[1];
		const db = binding('d1_databases');
		const media = binding('r2_buckets');
		expect(db).toBe('DB');
		expect(media).toBe('MEDIA');
		for (const key of [db!, media!, 'SETUP_TOKEN']) {
			expect(typeof bindings[key]?.description, key).toBe('string');
			expect(bindings[key].description.length, key).toBeGreaterThan(20);
		}
		// Uses the scripts the button runs.
		expect(pkg.scripts.build).toContain('vite build');
		expect(pkg.scripts.deploy).toBe('node scripts/deploy.mjs');
	});

	it('a fresh clone ignores the generated worker-configuration.d.ts', () => {
		expect(gitignore).toMatch(/^\/worker-configuration\.d\.ts$/m);
	});
});
